from ortools.sat.python import cp_model
import math
import json

def main():
    N = list(range(10))
    x_coords = [1.0, 1.5, 2.5, 3.5, 4.5, 2.0, 3.0, 4.0, 5.0, 3.8]
    y_coords = [2.0, 3.0, 1.5, 2.5, 1.8, 4.0, 3.5, 3.2, 2.8, 4.2]
    populations = [5200, 3800, 4500, 6100, 3500, 4200, 5500, 2800, 7300, 2100]
    R = 1.5
    K = 3

    coverage_sets = {}
    for i in N:
        coverage_sets[i] = []
        for j in N:
            distance = math.sqrt((x_coords[i] - x_coords[j])**2 + (y_coords[i] - y_coords[j])**2)
            if distance <= R:
                coverage_sets[i].append(j)

    model = cp_model.CpModel()

    select = {}
    covered = {}
    for i in N:
        select[i] = model.NewBoolVar(f"select_{i}")
        covered[i] = model.NewBoolVar(f"covered_{i}")

    model.Add(sum(select[i] for i in N) == K)

    for i in N:
        for j in coverage_sets[i]:
            model.Add(covered[i] >= select[j])

        sum_select_in_radius = sum(select[j] for j in coverage_sets[i])
        model.Add(covered[i] <= sum_select_in_radius)

    objective_terms = []
    for i in N:
        objective_terms.append(covered[i] * populations[i])

    model.Maximize(sum(objective_terms))

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 8
    status = solver.Solve(model)

    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        selected_neighborhoods = []
        total_covered_population = 0

        for i in N:
            if solver.Value(select[i]) == 1:
                selected_neighborhoods.append(i)
            if solver.Value(covered[i]) == 1:
                total_covered_population += populations[i]

        print(json.dumps({
            "selected_neighborhoods": selected_neighborhoods,
            "total_covered_population": total_covered_population
        }))
    else:
        print(json.dumps({
            "selected_neighborhoods": [],
            "total_covered_population": 0
        }))

if __name__ == "__main__":
    main()
